// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0) && newOwner != address(this));

        // Become the current owner via initialization: the constructor transfers ownership to msg.sender
        // We need to transfer ownership to newOwner first
        // But since the contract is already owned by the test contract (this), we do:
        c.transferOwnership(newOwner);

        // Now newOwner should accept
        vm.prank(newOwner);
        c.acceptOwnership();

        address actualOwner = c.owner();
        assertTrue(actualOwner == newOwner, "owner should be newOwner after acceptOwnership");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(newOwner != address(c) && newOwner != address(0) && caller != address(c));

        address originalOwner = c.owner();

        // Transfer ownership to newOwner (adds them as pending owner)
        vm.prank(originalOwner);
        c.transferOwnership(newOwner);

        // Now have 'caller' attempt acceptOwnership
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("acceptOwnership()"));

        // After the call, if it didn't revert, owner() should not be address(this)
        if (success) {
            address ownerAfter = c.owner();
            assertTrue(ownerAfter != address(c));
        }
    }
}

