pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(newOwner != address(0) && caller != address(0));
        vm.assume(newOwner != caller);

        // Transfer ownership to newOwner
        vm.prank(c.owner());
        c.transferOwnership(newOwner);

        // Call acceptOwnership as caller
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("acceptOwnership()"));

        // The general rule: if acceptOwnership succeeded, then newOwner is the owner; otherwise, owner is unchanged
        if (success) {
            assertTrue(c.owner() == newOwner, "acceptOwnership should set newOwner as owner");
        } else {
            assertTrue(c.owner() != newOwner, "acceptOwnership failed, owner should not become newOwner");
        }
    }
}

