pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address royaltyRecipient, uint256 tokenId) public {
        // bound tokenId to avoid collision with initialized tokenIdCounter (start at 1)
        vm.assume(tokenId > 0 && tokenId < 1e18);
        // Ensure royaltyRecipient is non-zero so initializeRoyalties succeeds
        vm.assume(royaltyRecipient != address(0));
        // We cannot call initialize directly, but we need to set up the contract
        // However, the contract is deployed without initialization, so we need to
        // drive it through a path that calls initializeRoyalties.
        // The contract's initialize function sets protocolFeeDestination and calls initializeRoyalties.
        // We can call initialize with dummy values to trigger that.
        // Use vm.prank to simulate the deployer calling initialize.
        vm.prank(address(0xdead));
        // initialize requires credChainId, credId, verificationType, protocolFeeDestination
        // We'll set protocolFeeDestination to royaltyRecipient; that gets passed to initializeRoyalties.
        c.initialize(1, 1, "test", royaltyRecipient);
        // Now getRoyalties for a token that hasn't been set (no custom royalties)
        ICreatorRoyaltiesControl.RoyaltyConfiguration memory config = c.getRoyalties(tokenId);
        // The reference: royaltyBPS should be 500, royaltyRecipient should be royaltyRecipient
        assertTrue(config.royaltyBPS == 500 && config.royaltyRecipient == royaltyRecipient);
    }
}

