            });

        // Try to call updateRoyalties; if it reverts, we assume the tokenId doesn't have a set royalty.
        // For the property, we only care about tokens where the call succeeds.
        try c.updateRoyalties(tokenId, config) {
            // success: the stored config is now set
        } catch {
